pts = [1, 5, 6, 7, 100]

def abs_cost(centre):
    return sum(abs(p - centre) for p in pts)

costs = {p: abs_cost(p) for p in pts}
assert costs[6] == 101
assert min(costs, key=costs.get) == 6
assert abs(sum(pts) / len(pts) - 23.8) < 1e-12
# PAM: medoids {0, 1} cost 19; swapping in 10 drops the cost to 2.
points = [0, 1, 10, 11]

def pam_cost(medoids):
    return sum(min(abs(p - m) for m in medoids) for p in points)

assert pam_cost([0, 1]) == 19
assert pam_cost([0, 10]) == 2
